css:
.d-dh{display:flex;flex-direction:column;width:100%;max-width:340px;height:200px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-dh-top{flex:1;min-height:0;padding:14px;display:flex;flex-direction:column;gap:2px;background:var(--bg)}
.d-dh-top b,.d-dh-bottom b{font-size:12px}
.d-dh-top span,.d-dh-bottom span{font-size:11px;color:var(--muted)}
.d-dh-handle{display:grid;place-items:center;height:14px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--paper);cursor:ns-resize;touch-action:none}
.d-dh-handle i{width:34px;height:3px;border-radius:999px;background:var(--line)}
.d-dh-bottom{height:96px;padding:14px;display:flex;flex-direction:column;gap:2px;background:var(--paper)}

init:
root => {
  var wrap = root.querySelector('[data-wrap]');
  var handle = root.querySelector('[data-handle]');
  var bottom = root.querySelector('[data-bottom]');
  var size = root.querySelector('[data-size]');
  if (!handle || !bottom) return;
  var startY = 0, startH = 0, drag = false;
  var apply = function (h) {
    var max = wrap.clientHeight * .7, min = 80;
    h = Math.max(min, Math.min(max, h));
    bottom.style.height = h.toFixed(1) + 'px';
    if (size) size.textContent = '高 ' + Math.round(h) + 'px';
  };
  handle.addEventListener('pointerdown', function (e) { drag = true; startY = e.clientY; startH = bottom.offsetHeight; handle.setPointerCapture(e.pointerId); });
  handle.addEventListener('pointermove', function (e) { if (!drag) return; apply(startH - (e.clientY - startY)); });
  var end = function () { drag = false; };
  handle.addEventListener('pointerup', end);
  handle.addEventListener('pointercancel', end);
}
